import{_ as s,o as t,c as r,a5 as o}from"./chunks/framework.CsGesDJn.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-10-list-workspace/report3_spec.md","filePath":"feature/agency-workspace/3-4-10-list-workspace/report3_spec.md"}'),n={name:"feature/agency-workspace/3-4-10-list-workspace/report3_spec.md"};function i(a,e,l,c,p,g){return t(),r("div",null,[...e[0]||(e[0]=[o("<p><strong>3.4.10 List Workspace</strong></p><p><strong>Function Trigger</strong></p><p>Begins when a signed-in user opens the Workspace list screen.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any Workspace member (MANAGER, CREATOR, or CLIENT).</li><li><strong>Purpose</strong>: Shows every Workspace the current user belongs to, so the user can pick one to work in.</li><li><strong>Interface</strong>: Workspace list screen of the current user - a list of Workspace entries, not scoped under an Agency route.</li><li><strong>Data Processing</strong>: The system reads the current user&#39;s active Workspace memberships, loads the Workspace records those memberships point to, and maps each one to a Workspace summary.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Workspace List Screen:</p><ul><li>A single grid screen titled with the user&#39;s Workspaces.</li><li>Each card shows an initials badge, the Workspace name, and its slug; clicking a card opens the Workspace settings screen.</li><li>An empty state message is shown when the user belongs to no Workspace.</li><li>A &quot;Create Workspace&quot; button navigates to the create form (FR 3.4.12).</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the caller&#39;s authenticated identity.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: active Workspace membership rows of the current user; the Workspace records those memberships reference.</li><li><strong>Output</strong>: the Workspaces the user belongs to - id, name, agencyId, slug, ownerId, settings, industry, companySize, website, phone, location, description, branding fields, social links, isActive, createdAt. The list card only renders name and slug.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-29</strong>: A Workspace is returned when either the current user has an active membership in it (MANAGER, CREATOR, CLIENT), or the current user is the Owner of the Agency that Workspace belongs to.</li><li><strong>BR-03</strong>: The listing is read-only; the only failure is a missing session, rejected with 401.</li><li>Known gap: soft-deleted Workspaces are not excluded from this list - the query has no status filter, so a deleted Workspace may still appear until fixed.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller must be signed in -&gt; otherwise 401.</li><li>A user with no Workspace membership receives an empty list, not an error.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>User opens the Workspace list screen.</li><li>System reads the current user&#39;s active Workspace memberships.</li><li>System loads the Workspace records referenced by those memberships.</li><li>System maps each Workspace to a Workspace summary.</li><li>Screen shows the Workspaces the user belongs to; an empty list is shown when the user belongs to none.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>5.a1: User belongs to no Workspace -&gt; empty list, HTTP 200. 5.a2: The empty state is displayed.</li><li>5.b1: User is not signed in -&gt; 401. 5.b2: The user is redirected to sign in.</li><li>5.c1: A soft-deleted Workspace is still referenced by an owned Agency or membership (known gap) -&gt; it is still returned and displayed as active. 5.c2: No client workaround; tracked as a backend fix.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>No data is changed; the Workspaces the user belongs to are displayed.</li></ul>",14)])])}const h=s(n,[["render",i]]);export{d as __pageData,h as default};
